import {
  forwardRef,
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
} from "react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardAction,
  CardContent,
  CardFooter,
  CardHeader,
  CardTitle,
  type CardProps,
} from "@/components/ui/card";
import { InputField, InputGroup } from "@/components/ui/input-group";
import { Select, SelectContent, SelectItem, SelectTrigger } from "@/components/ui/select";
import { useIcon } from "@/lib/icon-context";
import { nestedRadius, useShape } from "@/lib/shape-context";
import { useSize } from "@/lib/size-context";
import { SURFACE_BG, SURFACE_SHADOW } from "@/lib/surface-classes";
import { SurfaceProvider, useSurface } from "@/lib/surface-context";
import { cn } from "@/lib/utils";

export interface FineTuneValues {
  layout: number;
  width: number;
  height: number;
  radius: number;
  opacity: number;
  type: string;
}

export interface FineTuneCardProps extends Pick<CardProps, "className" | "size"> {
  defaultValues?: Partial<FineTuneValues>;
  onChange?: (values: FineTuneValues) => void;
  /** Accepted by the shared demo runtime. */
  variant?: string;
}

const DEFAULT_VALUES: FineTuneValues = {
  layout: 0,
  width: 324,
  height: 96,
  radius: 28,
  opacity: 100,
  type: "Select type",
};
const FIELDS = [
  { key: "width", label: "W", name: "Width", unit: "px", min: 40, max: 999 },
  { key: "height", label: "H", name: "Height", unit: "px", min: 24, max: 999 },
  { key: "radius", label: "Radius", name: "Radius", unit: "px", min: 0, max: 64 },
  { key: "opacity", label: "Opacity", name: "Opacity", unit: "%", min: 0, max: 100 },
] as const;
const LAYOUTS = ["Row", "Column", "Grid"];
const TYPE_OPTIONS = ["Seasonal", "Classic", "Limited"];

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, Math.round(value)));
}

function ScrubField({
  label,
  name,
  unit,
  value,
  onChange,
  min,
  max,
  index,
}: {
  label: string;
  name: string;
  unit: string;
  value: number;
  onChange: (value: number) => void;
  min: number;
  max: number;
  index: number;
}) {
  const shape = useShape();
  const size = useSize();
  const [draft, setDraft] = useState<string | null>(null);
  const drag = useRef<{ pointerId: number; x: number; value: number } | null>(null);

  function parse(text: string) {
    const next = Number(text);
    return text.trim() && Number.isFinite(next) ? clamp(next, min, max) : null;
  }
  function commit() {
    const next = parse(draft ?? String(value));
    if (next !== null) onChange(next);
    setDraft(null);
  }
  function handleKeyDown(event: KeyboardEvent<HTMLElement>) {
    const scrubbing = event.currentTarget.getAttribute("role") === "slider";
    const direction =
      event.key === "ArrowUp" || (scrubbing && event.key === "ArrowRight")
        ? 1
        : event.key === "ArrowDown" || (scrubbing && event.key === "ArrowLeft")
          ? -1
          : 0;
    if (direction) {
      event.preventDefault();
      onChange(
        clamp(
          (parse(draft ?? String(value)) ?? value) + direction * (event.shiftKey ? 10 : 1),
          min,
          max,
        ),
      );
      setDraft(null);
    } else if (scrubbing && (event.key === "Home" || event.key === "End")) {
      event.preventDefault();
      onChange(event.key === "Home" ? min : max);
      setDraft(null);
    } else if (event.key === "Enter") {
      commit();
    }
  }
  function stopDrag(event: PointerEvent<HTMLSpanElement>) {
    if (drag.current?.pointerId !== event.pointerId) return;
    drag.current = null;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
  }

  return (
    <div className="min-w-0" onBlurCapture={commit}>
      <InputField
        label={`${name} (${unit})`}
        labelHidden
        index={index}
        variant="filled"
        controlClassName="gap-1 px-1.5"
        leadingContent={
          <span
            role="slider"
            aria-label={`Adjust ${name} (${unit})`}
            aria-valuenow={value}
            aria-valuemin={min}
            aria-valuemax={max}
            aria-valuetext={`${value} ${unit}`}
            aria-orientation="horizontal"
            tabIndex={0}
            className={cn(
              "flex h-full shrink-0 cursor-ew-resize touch-none items-center select-none text-muted-foreground outline-none hover:text-foreground",
              shape.item,
              size.text,
            )}
            onKeyDown={handleKeyDown}
            onMouseDown={(event) => {
              event.preventDefault();
              event.stopPropagation();
            }}
            onPointerDown={(event) => {
              if (event.button !== 0 || drag.current) return;
              event.preventDefault();
              event.currentTarget.focus({ preventScroll: true });
              event.currentTarget.setPointerCapture(event.pointerId);
              drag.current = { pointerId: event.pointerId, x: event.clientX, value };
              setDraft(null);
            }}
            onPointerMove={(event) => {
              const start = drag.current;
              if (!start || start.pointerId !== event.pointerId) return;
              onChange(clamp(start.value + (event.clientX - start.x) / 2, min, max));
            }}
            onPointerUp={stopDrag}
            onPointerCancel={stopDrag}
            onLostPointerCapture={stopDrag}
          >
            {label}
          </span>
        }
        trailingContent={
          unit === "%" ? <span className="shrink-0 text-muted-foreground">%</span> : undefined
        }
        inputMode="numeric"
        min={min}
        max={max}
        step={1}
        value={draft ?? String(value)}
        onChange={(text) => {
          setDraft(text);
          const next = parse(text);
          if (next !== null) onChange(next);
        }}
        onKeyDown={handleKeyDown}
        className="min-w-0 [&_input]:min-w-[4ch] [&_input]:p-0 [&_input]:tabular-nums"
      />
    </div>
  );
}

function LayoutIcon({ layout, size }: { layout: number; size: number }) {
  const names = ["layout-row", "layout-column", "layout-grid"] as const;
  const Icon = useIcon(names[layout] ?? "layout-row");
  return (
    <span aria-hidden className="flex items-center justify-center leading-none">
      <Icon size={size} strokeWidth={1.5} className="block shrink-0" />
    </span>
  );
}

export const FineTuneCard = forwardRef<HTMLDivElement, FineTuneCardProps>(
  ({ defaultValues, onChange, className, size }, ref) => {
    const sizeClasses = useSize(size);
    const shape = useShape();
    const level = Math.min(8, Math.round(useSurface()) + 1);
    const typeLabelId = useId();
    const layoutRefs = useRef<(HTMLButtonElement | null)[]>([]);
    const onChangeRef = useRef(onChange);
    const [values, setValues] = useState<FineTuneValues>(() => {
      const initial = { ...DEFAULT_VALUES, ...defaultValues };
      initial.layout = clamp(Number.isFinite(initial.layout) ? initial.layout : 0, 0, 2);
      for (const { key, min, max } of FIELDS) {
        initial[key] = clamp(
          Number.isFinite(initial[key]) ? initial[key] : DEFAULT_VALUES[key],
          min,
          max,
        );
      }
      initial.type = defaultValues?.type ?? DEFAULT_VALUES.type;
      return initial;
    });

    useEffect(() => {
      onChangeRef.current = onChange;
    }, [onChange]);
    useEffect(() => {
      onChangeRef.current?.({ ...values });
    }, [values]);

    function update<K extends keyof FineTuneValues>(key: K, next: FineTuneValues[K]) {
      setValues((current) => (current[key] === next ? current : { ...current, [key]: next }));
    }
    const edited =
      values.layout !== DEFAULT_VALUES.layout ||
      values.type !== DEFAULT_VALUES.type ||
      FIELDS.some(({ key }) => values[key] !== DEFAULT_VALUES[key]);
    const caption = sizeClasses.variant === "compact" ? "text-[11px]" : "text-[12px]";
    const selectedType = values.type === DEFAULT_VALUES.type ? "" : values.type;
    const typeOptions =
      selectedType && !TYPE_OPTIONS.includes(selectedType)
        ? [selectedType, ...TYPE_OPTIONS]
        : TYPE_OPTIONS;

    return (
      <SurfaceProvider value={level}>
        <Card
          ref={ref}
          size={size}
          className={cn("w-full max-w-72 pb-0", SURFACE_BG[level], SURFACE_SHADOW[2], className)}
          style={
            {
              "--fine-tune-segment-radius": `${nestedRadius(shape.bgRadius, 2)}px`,
            } as CSSProperties
          }
        >
          <CardHeader className="items-center border-b border-border/60 px-4 py-3">
            <CardTitle className="text-[13px]">Flavor card</CardTitle>
            <CardAction
              className={cn(
                "row-span-1 flex items-center gap-1.5 self-center",
                edited
                  ? "text-[color:color-mix(in_oklab,var(--success,#22c55e)_65%,var(--foreground))]"
                  : "text-muted-foreground",
                caption,
              )}
              aria-live="polite"
              aria-atomic="true"
            >
              <span
                className={cn(
                  "flex size-4.5 items-center justify-center",
                  !edited && "bg-hover",
                  shape.item,
                )}
                aria-hidden
              >
                <svg
                  width="10"
                  height="10"
                  viewBox="0 0 24 24"
                  fill={edited ? "none" : "currentColor"}
                  stroke={edited ? "currentColor" : "none"}
                  strokeWidth={2}
                >
                  <path
                    d={
                      edited
                        ? "M20 6L9 17l-5-5"
                        : "M12 2l2.4 7.2L22 12l-7.6 2.8L12 22l-2.4-7.2L2 12l7.6-2.8z"
                    }
                  />
                </svg>
              </span>
              {edited ? "Edited" : "Adjust"}
            </CardAction>
          </CardHeader>
          <CardContent className="flex flex-col gap-2 px-4 py-4">
            <div className="flex flex-col gap-2">
              <span className="text-[12px] text-foreground">Layout</span>
              <div
                role="radiogroup"
                aria-label="Layout direction"
                className={cn("relative grid grid-cols-3 bg-hover p-0.5", shape.input)}
              >
                <span
                  aria-hidden
                  className={cn(
                    "pointer-events-none absolute inset-y-0.5 left-0.5 rounded-[var(--fine-tune-segment-radius)] transition-transform duration-180 motion-reduce:transition-none",
                    SURFACE_BG[Math.min(level + 3, 8)],
                    SURFACE_SHADOW[2],
                  )}
                  style={{
                    width: "calc((100% - 4px) / 3)",
                    transform: `translateX(${values.layout * 100}%)`,
                  }}
                />
                {LAYOUTS.map((label, index) => (
                  <Button
                    key={label}
                    ref={(node) => {
                      layoutRefs.current[index] = node;
                    }}
                    type="button"
                    role="radio"
                    aria-checked={values.layout === index}
                    aria-label={`${label} layout`}
                    tabIndex={values.layout === index ? 0 : -1}
                    variant="ghost"
                    size="icon-sm"
                    className={cn(
                      "relative h-6 w-full min-w-0 rounded-[var(--fine-tune-segment-radius)] [&_svg]:h-[18px] [&_svg]:w-[18px]",
                      values.layout === index && "text-foreground",
                    )}
                    onClick={() => update("layout", index)}
                    onKeyDown={(event) => {
                      let next: number;
                      if (event.key === "ArrowRight" || event.key === "ArrowDown")
                        next = (index + 1) % LAYOUTS.length;
                      else if (event.key === "ArrowLeft" || event.key === "ArrowUp")
                        next = (index + LAYOUTS.length - 1) % LAYOUTS.length;
                      else if (event.key === "Home") next = 0;
                      else if (event.key === "End") next = LAYOUTS.length - 1;
                      else return;
                      event.preventDefault();
                      update("layout", next);
                      layoutRefs.current[next]?.focus({ preventScroll: true });
                    }}
                  >
                    <LayoutIcon layout={index} size={18} />
                  </Button>
                ))}
              </div>
            </div>
            <InputGroup size="compact" axis="xy" className="grid w-full grid-cols-2 gap-2">
              {FIELDS.map(({ key, ...field }, index) => (
                <ScrubField
                  key={key}
                  {...field}
                  index={index}
                  value={values[key]}
                  onChange={(next) => update(key, next)}
                />
              ))}
            </InputGroup>
          </CardContent>
          <CardFooter className="justify-between border-t border-border/60 px-4 py-3">
            <span id={typeLabelId} className="text-[12px] text-muted-foreground">
              Type
            </span>
            <Select
              size="compact"
              value={selectedType}
              onValueChange={(next) => update("type", next)}
            >
              <SelectTrigger
                aria-labelledby={typeLabelId}
                variant="borderless"
                placeholder="Select type"
                className="h-7 w-30 min-w-0 bg-hover px-2 text-[12px]"
              />
              <SelectContent>
                {typeOptions.map((type, index) => (
                  <SelectItem key={type} value={type} index={index}>
                    {type}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </CardFooter>
        </Card>
      </SurfaceProvider>
    );
  },
);

FineTuneCard.displayName = "FineTuneCard";

export default FineTuneCard;
